import { z } from 'zod';
export const orderRequestSchema = z.object({
  client_order_id: z.uuid(), district: z.string().min(1).max(80),
  items: z.array(z.object({ product_id: z.string().min(1).max(80), qty: z.number().int().min(1).max(99) }).strict()).min(1).max(40),
  age_confirmed: z.literal(true), age_verification_token: z.string().min(1).max(4096).optional(),
}).strict().refine(value => new Set(value.items.map(item => item.product_id)).size === value.items.length,
  { message: 'Duplicate product IDs are not allowed' });
export const telegramUserSchema = z.object({ id: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
  first_name: z.string().max(200), username: z.string().max(100).optional() });
